require __DIR__.'/../bootstrap.php'; require_admin(); if($_SERVER['REQUEST_METHOD']!=='POST') respond(['success'=>false,'message'=>'Method tidak diizinkan.'],405); check_csrf(); $d=json_input(); $kind=$d['kind']??''; $id=(int)($d['id']??0); $status=$d['status']??''; if($id<1||!in_array($kind,['report','collection'],true)) respond(['success'=>false,'message'=>'Data tidak valid.'],422);
if($kind==='report'){if(!in_array($status,['in_progress','resolved','rejected'],true))respond(['success'=>false,'message'=>'Status tidak valid.'],422);$q=$pdo->prepare('UPDATE reports SET status=? WHERE id=?');$q->execute([$status,$id]);}
else {if(!in_array($status,['approved','rejected'],true))respond(['success'=>false,'message'=>'Status tidak valid.'],422);$pdo->beginTransaction();$q=$pdo->prepare('SELECT user_id,weight_kg,status FROM collections WHERE id=? FOR UPDATE');$q->execute([$id]);$c=$q->fetch();if(!$c){$pdo->rollBack();respond(['success'=>false,'message'=>'Pengajuan tidak ditemukan.'],404);}if($c['status']!=='pending'){$pdo->rollBack();respond(['success'=>false,'message'=>'Pengajuan sudah ditinjau.'],409);} $points=$status==='approved'?(int)floor((float)$c['weight_kg']*100):0;$pdo->prepare('UPDATE collections SET status=?,points_awarded=? WHERE id=?')->execute([$status,$points,$id]);if($points>0){$pdo->prepare('UPDATE users SET points=points+? WHERE id=?')->execute([$points,$c['user_id']]);$pdo->prepare('INSERT INTO point_transactions(user_id,points,description) VALUES(?,?,?)')->execute([$c['user_id'],$points,'Verifikasi pengumpulan #'.$id]);}$pdo->commit();}
respond(['success'=>true,'message'=>'Status berhasil diperbarui.']);
